<script lang="ts">import type { InstanceForm } from "../../instance-form"; let { form = $bindable() }: { form: InstanceForm } = $props();</script>
<div class="form-grid equal"><label>Security<select bind:value={form.xray_security}><option value="reality">REALITY</option><option value="tls">TLS certificate</option></select></label><label>Transport<select bind:value={form.xray_transport}><option value="tcp">TCP</option><option value="xhttp">XHTTP</option>{#if form.xray_security === "tls"}<option value="mkcp">mKCP</option>{/if}</select></label></div><div class="form-grid equal"><label>SNI / camouflage host<input bind:value={form.xray_server_name} required placeholder="www.example.com" /></label><label>Client fingerprint<select bind:value={form.xray_fingerprint}><option value="chrome">Chrome</option><option value="firefox">Firefox</option><option value="safari">Safari</option><option value="edge">Edge</option><option value="randomized">Randomized</option></select></label></div>{#if form.xray_transport === "xhttp"}<label>XHTTP path<input bind:value={form.xray_xhttp_path} required placeholder="/" /></label>{/if}{#if form.xray_security === "tls"}<div class="form-grid equal"><label>Certificate file path<input bind:value={form.xray_certificate_path} required placeholder="C:\certs\fullchain.pem" /></label><label>Private-key file path<input type="password" bind:value={form.xray_private_key_path} required autocomplete="off" placeholder="C:\certs\private-key.pem" /></label></div><p class="help">Only file paths cross the desktop bridge. Rust reads and validates the files; PEM contents never enter Svelte state.</p>{:else}<p class="help">REALITY private material is generated remotely during verified deployment. Only its public key and short ID are retained in desired state.</p>{/if}
